sys.stdout.reconfigure(encoding="utf-8")
ROOT = r"C:\Users\eric_rash\Desktop\DEV\Flint\staging"
LIB = os.path.join(ROOT, r"library\sports-analytics-and-decision-making\ssac-talks--42analytics")
SRC = os.path.join(ROOT, r"sources\42analytics")
MINE = "npgdKKdJSww AgouMNTeyo4 40NV3_u9tYY BJkCqf6Fj2w J7smyg1Czik sHXuxj3-rbQ QLdbKUiNadg TbYgc6_qQzo EeBgUCYhezc SIn6IyYQEVI TIRINmtZOu0 z_6M5r7031A".split()
ALL = MINE + "oZsFyPGij0U -6pe_zOKCig Q3i3FOC-dPE teg9SfzpMy0 1nt8hK2oYrE K5a7C4b1Cwc o4rMbhsdk0I pcp9h_M6Ir8 JHgeEo3n1do JjeFktc4QLM an7u-tVP5Xc".split()
def ts(s):
    p = [int(x) for x in s.split(":")]
    return p[0]*60+p[1] if len(p)==2 else p[0]*3600+p[1]*60+p[2]
trans = {}
for vid in MINE:
    d = [x for x in glob.glob(os.path.join(SRC, "*")) if vid in os.path.basename(x)][0]
    t = open(os.path.join(d, "transcript.md"), encoding="utf-8").read()
    # split into blocks by marker
    parts = re.split(r"\[(\d+:\d{2}(?::\d{2})?)\]", t)
    blocks = {}
    for i in range(1, len(parts), 2):
        blocks[ts(parts[i])] = parts[i+1]
    trans[vid] = (t, blocks)
    print(vid, "last marker", max(blocks) // 60, ":", max(blocks) % 60, "nblocks", len(blocks))
files = sorted(glob.glob(os.path.join(LIB, "*.md")))
names = {os.path.basename(f)[:-3] for f in files}
mode = sys.argv[1] if len(sys.argv) > 1 else "all"
for f in files:
    bn = os.path.basename(f)
    if bn.startswith("_"): continue
    txt = open(f, encoding="utf-8").read()
    m = re.search(r'^chapter:\s*"?([^"\n]+)"?', txt, re.M)
    ch = m.group(1).strip() if m else None
    ids = sorted({i for i in ALL if i in txt})
    if not any(i in MINE for i in ids): continue
    issues = []
    fm = txt.split("---")[1]
    keys = re.findall(r"^([a-z-]+):", fm, re.M)
    exp = ["type","kind","domain","book","chapter","topic","category","confidence","ingest-tier","created","source"]
    if keys != exp: issues.append(f"keys {keys}")
    kind = re.search(r"^kind:\s*(\S+)", fm, re.M).group(1)
    if not bn.startswith(kind+"--"): issues.append("kind/prefix mismatch")
    conf = re.search(r"^confidence:\s*(\S+)", fm, re.M).group(1)
    if conf not in ("supported","untested","contested"): issues.append("conf "+conf)
    if not re.search(r'^chapter: "', fm, re.M): issues.append("chapter not quoted")
    if "created: 2026-10-01" not in fm: issues.append("created")
    body = txt.split("---",2)[2]
    for h in ["What it is","Why it works","When to apply","When NOT to apply","Example","Related"]:
        if f"**{h}** —" not in body: issues.append("hdr "+h)
    b2 = re.sub(r"\*\*[^*]+\*\* —", "", body)
    if "—" in b2: issues.append("em dash in body")
    if re.search(r"prior version|corrected from|NO-GO|review round|reviewer", body, re.I): issues.append("review history phrase")
    for l in re.findall(r"\[\[([^\]|#]+)", body):
        l2 = l.split("/")[-1]
        if l2 not in names: issues.append("link? "+l)
    # locators
    for vid in ids:
        if vid not in MINE: continue
        blocks = trans[vid][1]
        for mm in re.finditer(re.escape(vid)+r"\s*\[(\d+:\d{2})\]((?:\s*(?:to|,|and|-)\s*\[\d+:\d{2}\])*)", body):
            locs = [mm.group(1)] + re.findall(r"\[(\d+:\d{2})\]", mm.group(2))
            for loc in locs:
                if ts(loc) not in blocks: issues.append(f"loc {vid} [{loc}] not a marker")
        # bare [mm:ss] not preceded by id
    for mm in re.finditer(r"(?<![A-Za-z0-9_-] )(?<!\w)\[(\d+:\d{2})\]", body):
        pass
    print(f"{ch}|{bn}|{conf}|ids={' '.join(ids)}|{'; '.join(issues) if issues else 'ok'}")

